mapper.select:
/*selectMasterMdCmCmsItemChangeReqStatusList*/ SELECT H.REQ_NO /* 요청번호 */ ,H.CMS_CATLG_ID /* 상품정보코드 */ ,H.REQ_STATUS /* 진행상태(원코드) */ /* 진행상태명 : 공통코드 ICOMCOD1 TYPE='CMSRSTTS' (REQ/APR/REJ/CAN). ⚠ 코드행이 없으면 이 열은 공란이 된다 - 코드 적재가 선행이다 */ ,(SELECT ST.TEXT1 FROM ICOMCOD1 ST WHERE ST.TYPE = 'CMSRSTTS' AND ST.CODE = H.REQ_STATUS) AS REQ_STATUS_NM /* 진행상태 */ /* ↓ 요청 시점 스냅샷. CMSCATLG 현재값이 아니다 - 승인 후에도 요청 당시 화면이 그대로 남는다 */ ,DECODE(H.STATUS, 'D', '미사용', '사용') AS STATUS_NM /* 상품상태 */ ,H.DESCRIPTION_LOC /* 품목명 */ ,H.MODEL_INFO /* 모델번호 */ ,H.SPECIFICATION /* 규격 */ ,(SELECT MK.TEXT1 FROM ICOMCOD1 MK WHERE MK.TYPE = 'M104' AND MK.CODE = H.MAKER_CODE) AS MAKER_NAME /* 제조사명 */ ,H.MAKER_CODE /* 제조사코드 */ ,(SELECT OG.TEXT2 FROM ICOMCOD1 OG WHERE OG.TYPE = 'M001' AND OG.CODE = H.ORIGIN_CODE) AS ORIGIN_NAME /* 원산지명 */ ,H.ORDER_MEASURE /* 단위 */ ,D.REQ_SEQ /* 변경항목 순번 */ ,D.JOB_COLUMN /* 변경항목(원컬럼명) */
/* 변경사유 : 상품상태는 사유코드(M182), 그 외는 텍스트 (상태변경 팝업 규약과 동일) */ ,NVL((SELECT RS.TEXT1 FROM ICOMCOD1 RS WHERE RS.TYPE = 'M182' AND RS.CODE = D.CHANGE_REASON_CODE) , D.CHANGE_REASON_REMARK) AS CHANGE_REASON /* 변경사유 */ /* 대체코드 : 사유가 '중복존재'(DUP)일 때만 값이 있다 */ ,CASE WHEN D.CHANGE_REASON_CODE = 'DUP' THEN D.ALT_CATLG_ID ELSE '' END AS ALT_CODE /* 대체코드 */ ,(SELECT U1.USER_NAME_LOC FROM ICOMLUSR U1 WHERE U1.USER_ID = H.REQ_USER_ID) AS REQ_USER_NAME /* 요청자 */ ,H.REQ_USER_ID /* 요청자 ID */ ,SUBSTR(H.REQ_DATE,1,4) || '/' || SUBSTR(H.REQ_DATE,5,2) || '/' || SUBSTR(H.REQ_DATE,7,2) || ' ' || SUBSTR(H.REQ_TIME,1,2) || ':' || SUBSTR(H.REQ_TIME,3,2) AS REQ_DATETIME /* 요청일시 */ ,H.REJECT_REASON /* 반려사유 */ ,(SELECT U3.USER_NAME_LOC FROM ICOMLUSR U3 WHERE U3.USER_ID = H.PROC_USER_ID) AS PROC_USER_NAME /* 처리담당자 */ /* 처리일시 : 승인·반려·취소된 건에만 값이 있다 (진행상태 '요청'이면 공란) */ ,CASE WHEN H.PROC_DATE IS NULL THEN '' ELSE SUBSTR(H.PROC_DATE,1,4) || '/' || SUBSTR(H.PROC_DATE,5,2) || '/' || SUBSTR(H.PROC_DATE,7,2) || ' ' || SUBSTR(H.PROC_TIME,1,2) || ':' || SUBSTR(H.PROC_TIME,3,2) END AS PROC_DATETIME /* 처리일시 */ /* 이 요청번호의 변경항목 수 - 목업의 '복수항목 요청건수 3건' */ ,(SELECT COUNT(*) FROM CMSCATLG_REQ_DT C WHERE C.REQ_NO = H.REQ_NO) AS ITEM_CNT /* 변경항목수 */ FROM CMSCATLG_REQ H, CMSCATLG_REQ_DT D WHERE H.REQ_NO = D.REQ_NO /* ★ 본인이 낸 요청만 보이는 화면이다(2026-09-07 사용자 결정). 로그인 사용자는 컨트롤러가 세션에서 넣는다 - 화면이 보낸 값은 쓰지 않는다. 값이 비면 0건이 되는 게 맞다(세션 없이 들어온 요청). */ AND H.REQ_USER_ID = #{st_login_user_id}
AND H.REQ_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND H.REQ_NO IN
#{item}
AND H.REQ_NO = #{st_req_no}
AND H.CMS_CATLG_ID IN
UPPER(#{item})
AND H.CMS_CATLG_ID = UPPER(#{st_cmscatlg})
AND EXISTS (SELECT 1 FROM CMSCATLG_REQ_DT C2 WHERE C2.REQ_NO = H.REQ_NO AND C2.JOB_COLUMN = #{st_job_column})
AND (SELECT COUNT(*) FROM CMSCATLG_REQ_DT C WHERE C.REQ_NO = H.REQ_NO) = 1
AND (SELECT COUNT(*) FROM CMSCATLG_REQ_DT C WHERE C.REQ_NO = H.REQ_NO) > 1
AND H.DESCRIPTION_LOC LIKE '%' || #{st_item_name} || '%'
AND H.MODEL_INFO LIKE '%' || #{st_model_info} || '%'
AND H.SPECIFICATION LIKE '%' || #{st_specification} || '%'
AND H.MAKER_CODE = #{st_maker_code}
AND EXISTS (SELECT 1 FROM ICOMLUSR U WHERE U.USER_ID = H.REQ_USER_ID AND U.USER_NAME_LOC LIKE '%' || #{st_req_user_name} || '%')
AND H.REQ_STATUS = #{st_req_status}
ORDER BY H.REQ_NO DESC, D.REQ_SEQ

mapper.update:

/*updateMasterMdCmCmsItemChangeReqCancel*/
UPDATE CMSCATLG_REQ
   SET REQ_STATUS   = 'CAN'
     , PROC_USER_ID = #{st_user_id}
     , PROC_DATE    = TO_CHAR(SYSDATE,'YYYYMMDD')
     , PROC_TIME    = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE REQ_NO      = #{st_req_no}
   AND REQ_STATUS  = 'REQ'
   AND REQ_USER_ID = #{st_user_id}
